package com.bytbeat.mpctrainer

import android.app.Activity
import android.app.Application
import android.content.Context
import android.graphics.Color
import android.graphics.Typeface
import android.graphics.drawable.GradientDrawable
import android.graphics.drawable.StateListDrawable
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.view.Gravity
import android.view.View
import android.view.ViewGroup
import android.widget.*
import androidx.appcompat.app.AlertDialog
import org.json.JSONObject

/** Compact MPC-inspired hardware surface: larger working display -> controls -> banks -> 4x4 pads -> transport. */
class TrainerApp:Application(),Application.ActivityLifecycleCallbacks{
 private val ui=Handler(Looper.getMainLooper());private var pulse:Runnable?=null;private var lastPadSerial=-1L;private var litPad=-1;private var litSerial=-1L
 override fun onCreate(){super.onCreate();registerActivityLifecycleCallbacks(this)}
 override fun onActivityResumed(activity:Activity){if(activity !is TrainerActivity)return;val content=activity.findViewById<FrameLayout>(android.R.id.content)?:return;if(content.tag!="phone_ui_v14"){val root=content.getChildAt(0) as? LinearLayout?:return;rebuild(activity,root);content.tag="phone_ui_v14"};startIndicators(activity)}
 override fun onActivityPaused(a:Activity){stopIndicators()}
 private fun rebuild(a:TrainerActivity,root:LinearLayout){
  root.setPadding(a.dp(8),a.dp(4),a.dp(8),a.dp(5));root.setBackgroundColor(Color.rgb(202,198,187))
  findText(root){it.text?.toString()?.startsWith("MPC TRAINER")==true}?.apply{text="MPC LIVE III     TRAINER";textSize=11.5f;typeface=Typeface.DEFAULT_BOLD;letterSpacing=.035f;gravity=Gravity.CENTER_VERTICAL;setTextColor(Color.rgb(42,40,37));setPadding(a.dp(5),0,0,a.dp(1));layoutParams=layoutParams.apply{height=a.dp(28)}}
  findText(root){it.text?.toString()?.startsWith("SEQ")==true}?.apply{textSize=11f;typeface=Typeface.MONOSPACE;gravity=Gravity.TOP or Gravity.START;minHeight=0;setPadding(a.dp(12),a.dp(10),a.dp(12),a.dp(8));layoutParams=layoutParams.apply{height=a.dp(112)};background=rounded(Color.rgb(17,28,25),Color.rgb(6,10,9),a.dp(2),a.dp(4));setTextColor(Color.rgb(190,235,179))}
  val rows=(0 until root.childCount).mapNotNull{root.getChildAt(it) as? LinearLayout}.filter{it.orientation==LinearLayout.HORIZONTAL}
  rows.forEach{row->val labels=(0 until row.childCount).mapNotNull{(row.getChildAt(it) as? Button)?.text?.toString()};val transport=labels.any{it in setOf("REC","OVERDUB","STOP","PLAY")};val bankRow=labels.any{it.startsWith("BANK ")};row.setPadding(0,if(transport)a.dp(3) else 0,0,if(transport)a.dp(3) else 0);row.layoutParams=row.layoutParams.apply{height=if(transport)a.dp(54) else if(bankRow)a.dp(43) else a.dp(42)};for(i in 0 until row.childCount)(row.getChildAt(i) as? Button)?.apply{minHeight=0;minimumHeight=0;textSize=if(transport)9.2f else 8.1f;typeface=if(transport)Typeface.DEFAULT_BOLD else Typeface.DEFAULT;letterSpacing=.015f;isAllCaps=false;setPadding(a.dp(2),0,a.dp(2),0);background=if(transport)transportSelector(a) else buttonSelector(a);setTextColor(Color.rgb(42,41,38))}}
  val grid=findFirst(root,GridLayout::class.java)
  if(grid!=null){val available=a.resources.displayMetrics.heightPixels-a.dp(112+28+43+42*3+54+42+80);val maxGridWidth=(a.resources.displayMetrics.widthPixels-a.dp(16)).coerceAtMost(a.dp(390));val gridSize=maxGridWidth.coerceAtMost(available.coerceAtLeast(a.dp(250)));(grid.layoutParams as? LinearLayout.LayoutParams)?.let{lp->lp.height=gridSize;lp.weight=0f;lp.topMargin=a.dp(5);lp.bottomMargin=a.dp(5);grid.layoutParams=lp};val gap=a.dp(4);val cell=(gridSize-gap*3)/4;for(i in 0 until grid.childCount)(grid.getChildAt(i) as? Button)?.apply{minHeight=0;minimumHeight=0;textSize=8.4f;typeface=Typeface.create(Typeface.SANS_SERIF,Typeface.NORMAL);setPadding(a.dp(4),a.dp(4),a.dp(4),a.dp(4));setTextColor(Color.rgb(231,230,223));gravity=Gravity.CENTER;background=padSelector(a);layoutParams=GridLayout.LayoutParams().apply{width=cell;height=cell;columnSpec=GridLayout.spec(i%4);rowSpec=GridLayout.spec(i/4);setMargins(if(i%4==0)0 else gap,if(i/4==0)0 else gap,0,0)}}}
  val restart=findButton(root,"RESTART COURSE");val guide=findButton(root,"CONTROL GUIDE");restart?.visibility=View.GONE;guide?.visibility=View.GONE;rows.firstOrNull{row->(0 until row.childCount).any{row.getChildAt(it)===restart||row.getChildAt(it)===guide}}?.visibility=View.GONE;addUtilityBar(a,root,restart,guide)
 }
 private fun addUtilityBar(a:TrainerActivity,root:LinearLayout,restart:Button?,guide:Button?){val bar=LinearLayout(a).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(0,a.dp(4),0,0)};val tempo=Button(a).apply{text="TEMPO";textSize=8.2f;typeface=Typeface.DEFAULT_BOLD;isAllCaps=false;background=darkUtilitySelector(a);setTextColor(Color.rgb(221,220,212));setOnClickListener{showBpm(a)}};val menu=Button(a).apply{text="MENU";textSize=8.2f;typeface=Typeface.DEFAULT_BOLD;isAllCaps=false;background=darkUtilitySelector(a);setTextColor(Color.rgb(221,220,212));setOnClickListener{showMenu(a,restart,guide)}};bar.addView(tempo,LinearLayout.LayoutParams(0,a.dp(42),1f));bar.addView(menu,LinearLayout.LayoutParams(0,a.dp(42),1f));root.addView(bar)}
 private fun showMenu(a:TrainerActivity,restart:Button?,guide:Button?){val items=arrayOf("MIXER / VOLUME","CONTROL GUIDE","RESTART COURSE","NEW PROJECT");AlertDialog.Builder(a).setTitle("MPC TRAINER • MENU").setItems(items){_,which->when(which){0->a.showVolumeMixer();1->guide?.performClick();2->restart?.performClick();3->confirmNewProject(a)}}.setNegativeButton("ЗАКРЫТЬ",null).show()}
 private fun startIndicators(a:TrainerActivity){stopIndicators();val root=a.findViewById<ViewGroup>(android.R.id.content)?:return;val grid=findFirst(root,GridLayout::class.java);val r=object:Runnable{override fun run(){LearnSurfaceStyler.update(a,root);val s=TrainerUiState.snapshot;for(i in 0..3)setLed(a,root,"BANK ${'A'+i}",s.bank==i,Color.rgb(35,167,210));setLed(a,root,"REC",s.recording&&!s.overdub,Color.rgb(226,55,45),true);setLed(a,root,"OVERDUB",s.recording&&s.overdub,Color.rgb(237,125,31),true);setLed(a,root,"PLAY",s.playing&&!s.recording,Color.rgb(64,188,91),true);setLed(a,root,"NOTE REPEAT",s.noteRepeat,Color.rgb(216,62,139));setLed(a,root,"FULL LEVEL",s.fullLevel,Color.rgb(229,175,48));setLed(a,root,"16 LEVELS",s.levels16,Color.rgb(43,183,207));setLed(a,root,"TRACK MUTE",s.trackMuted,Color.rgb(218,59,52));if(s.activeSerial!=lastPadSerial){lastPadSerial=s.activeSerial;if(s.activeBank==s.bank&&s.activePad in 0..15){val pad=s.activePad;val serial=s.activeSerial;if(litPad>=0&&litPad!=pad)paintPad(a,grid,litPad,false);litPad=pad;litSerial=serial;paintPad(a,grid,pad,true);ui.postDelayed({if(litPad==pad&&litSerial==serial){paintPad(a,grid,pad,false);litPad=-1;litSerial=-1}},90)}};ui.postDelayed(this,30)}};pulse=r;ui.post(r)}
 private fun paintPad(a:Activity,grid:GridLayout?,i:Int,on:Boolean){(grid?.getChildAt(i) as? Button)?.background=if(on)rounded(Color.rgb(69,74,67),Color.rgb(37,201,217),a.dp(3),a.dp(5)) else padSelector(a)}
 private fun setLed(a:Activity,root:View,label:String,on:Boolean,c:Int,transport:Boolean=false){findButton(root,label)?.apply{background=if(on)ledButton(a,c,transport) else if(transport)transportSelector(a) else buttonSelector(a);setTextColor(if(on)Color.rgb(18,18,17) else Color.rgb(42,41,38))}}
 private fun stopIndicators(){pulse?.let{ui.removeCallbacks(it)};pulse=null;litPad=-1;litSerial=-1}
 private fun padSelector(a:Activity)=StateListDrawable().apply{addState(intArrayOf(android.R.attr.state_pressed),rounded(Color.rgb(67,68,63),Color.rgb(37,201,217),a.dp(3),a.dp(5)));addState(intArrayOf(),rounded(Color.rgb(55,54,51),Color.rgb(91,88,81),a.dp(1),a.dp(5)))}
 private fun buttonSelector(a:Activity)=StateListDrawable().apply{addState(intArrayOf(android.R.attr.state_pressed),rounded(Color.rgb(172,171,164),Color.rgb(95,92,86),a.dp(1),a.dp(3)));addState(intArrayOf(),rounded(Color.rgb(190,189,182),Color.rgb(137,134,126),a.dp(1),a.dp(3)))}
 private fun transportSelector(a:Activity)=StateListDrawable().apply{addState(intArrayOf(android.R.attr.state_pressed),rounded(Color.rgb(129,128,122),Color.rgb(70,69,65),a.dp(2),a.dp(3)));addState(intArrayOf(),rounded(Color.rgb(163,162,155),Color.rgb(105,102,95),a.dp(1),a.dp(3)))}
 private fun darkUtilitySelector(a:Activity)=StateListDrawable().apply{addState(intArrayOf(android.R.attr.state_pressed),rounded(Color.rgb(53,53,50),Color.rgb(20,20,19),a.dp(2),a.dp(3)));addState(intArrayOf(),rounded(Color.rgb(72,71,67),Color.rgb(42,40,37),a.dp(1),a.dp(3)))}
 private fun ledButton(a:Activity,c:Int,transport:Boolean=false)=rounded(if(transport)Color.rgb(158,158,151) else Color.rgb(181,188,184),c,a.dp(3),a.dp(3))
 private fun showBpm(a:TrainerActivity){val prefs=a.getSharedPreferences("trainer_v2",Context.MODE_PRIVATE);val raw=prefs.getString("project",null);val obj=try{if(raw!=null)JSONObject(raw)else JSONObject()}catch(_:Exception){JSONObject()};val current=obj.optInt("bpm",90).coerceIn(40,240);val box=LinearLayout(a).apply{orientation=LinearLayout.VERTICAL;setPadding(a.dp(20),a.dp(8),a.dp(20),0)};val value=TextView(a).apply{textSize=22f;text="$current BPM"};val seek=SeekBar(a).apply{max=200;progress=current-40};seek.setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(s:SeekBar?,p:Int,f:Boolean){value.text="${p+40} BPM"};override fun onStartTrackingTouch(s:SeekBar?){};override fun onStopTrackingTouch(s:SeekBar?){}});box.addView(value);box.addView(seek);AlertDialog.Builder(a).setTitle("TEMPO").setView(box).setNegativeButton("ОТМЕНА",null).setPositiveButton("УСТАНОВИТЬ"){_,_->obj.put("bpm",seek.progress+40);prefs.edit().putString("project",obj.toString()).apply();a.recreate()}.show()}
 private fun confirmNewProject(a:TrainerActivity){AlertDialog.Builder(a).setTitle("NEW PROJECT").setMessage("Очистить назначения пэдов, события Sequence, громкости и настройки проекта? Импортированные исходные аудиофайлы останутся на телефоне.").setNegativeButton("ОТМЕНА",null).setPositiveButton("NEW PROJECT"){_,_->val e=a.getSharedPreferences("trainer_v2",Context.MODE_PRIVATE).edit();ProjectReset.preferenceKeys().forEach(e::remove);e.apply();a.recreate()}.show()}
 private fun rounded(fill:Int,stroke:Int,strokeWidth:Int,radius:Int)=GradientDrawable().apply{shape=GradientDrawable.RECTANGLE;setColor(fill);setStroke(strokeWidth,stroke);cornerRadius=radius.toFloat()}
 private fun findButton(root:View,label:String)=findFirst(root,Button::class.java){it.text?.toString()==label};private fun findText(root:View,p:(TextView)->Boolean)=findFirst(root,TextView::class.java,p)
 private fun <T:View> findFirst(root:View,type:Class<T>,p:(T)->Boolean={true}):T?{if(type.isInstance(root)){val v=type.cast(root);if(v!=null&&p(v))return v};if(root is ViewGroup)for(i in 0 until root.childCount){val f=findFirst(root.getChildAt(i),type,p);if(f!=null)return f};return null}
 private fun Activity.dp(v:Int)=(v*resources.displayMetrics.density+0.5f).toInt()
 override fun onActivityCreated(a:Activity,b:Bundle?){};override fun onActivityStarted(a:Activity){};override fun onActivityStopped(a:Activity){};override fun onActivitySaveInstanceState(a:Activity,b:Bundle){};override fun onActivityDestroyed(a:Activity){stopIndicators()}
}
